import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

test('router has exactly five routes in expected order and methods', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({method: r.method, path: r.path})),
    [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ]
  );
});

test('successful handling across all routes', async () => {
  const router = makeRouter();
  const mockRes = {
    send(val) {
      return val;
    },
  };
  const noopNext = () => {
    throw new Error('next should not be called on success');
  };

  // GET /accounts/:id
  const getAcc = router.routes[0];
  const accResult = await getAcc.handler({id: '123'}, mockRes, noopNext);
  assert.equal(accResult, 'account:123');

  // POST /accounts
  const postAcc = router.routes[1];
  const postResult = await postAcc.handler({id: '456'}, mockRes, noopNext);
  assert.equal(postResult, 'created:456');

  // GET /health (synchronous route)
  const healthRoute = router.routes[2];
  const healthResult = healthRoute.handler({id: '0'}, mockRes, noopNext);
  assert.equal(healthResult, 'ok');

  // GET /orders/:id
  const getOrder = router.routes[3];
  const orderResult = await getOrder.handler({id: 'abc'}, mockRes, noopNext);
  assert.equal(orderResult, 'ABC');

  // DELETE /orders/:id
  const delOrder = router.routes[4];
  const delResult = await delOrder.handler({id: 'xyz'}, mockRes, noopNext);
  assert.equal(delResult, 'deleted:xyz');
});

test('error forwarding via next for registered async routes', async () => {
  const router = makeRouter();
  const mockRes = {
    send(val) {
      return val;
    },
  };

  const testErrorForwarding = async (routeIndex, expectedMessage) => {
    const route = router.routes[routeIndex];
    let forwardedError = null;
    const next = (err) => {
      forwardedError = err;
    };

    // The wrapped handler should catch the rejection and pass it to next, not throw/reject
    await route.handler({fail: true, id: 'test'}, mockRes, next);
    assert.ok(forwardedError instanceof Error, `Expected Error for route ${route.method} ${route.path}`);
    assert.equal(forwardedError.message, expectedMessage);
  };

  // GET /accounts/:id
  await testErrorForwarding(0, 'account read');

  // POST /accounts (named async function)
  await testErrorForwarding(1, 'account create');

  // GET /orders/:id
  await testErrorForwarding(3, 'order read');

  // DELETE /orders/:id
  await testErrorForwarding(4, 'order delete');
});

test('synchronous /health route is not wrapped with withErrors', () => {
  const router = makeRouter();
  const healthHandler = router.routes[2].handler;
  // withErrors returns an async function; health handler is a synchronous function
  const result = healthHandler({id: '1'}, {send: v => v}, () => {});
  assert.equal(result, 'ok');
  assert.equal(healthHandler.constructor.name, 'Function');
});

test('unrelated helpers and callbacks remain unmodified', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");
  await assert.rejects(async () => {
    await unrelatedHelper();
  }, /helper/);
  await assert.rejects(async () => {
    await auditCallback();
  }, /audit/);
});

